// Tier icon & color
const getTierConfig = (theme, tier, customColor) => {
  const isLight = theme.palette.mode === 'light';
  
  const defaults = {
    diamond: { 
      icon: <DiamondIcon />, 
      color: isLight ? '#00838f' : '#4dd0e1', 
      bg: isLight ? 'linear-gradient(135deg, #e0f7fa 0%, #b2ebf2 100%)' : 'linear-gradient(135deg, #006064 0%, #00838f 100%)',
    },
    gold: { 
      icon: <TrophyIcon />, 
      color: isLight ? '#f57f17' : '#ffd54f', 
      bg: isLight ? 'linear-gradient(135deg, #fff8e1 0%, #ffe082 100%)' : 'linear-gradient(135deg, #f57f17 0%, #ffb300 100%)',
    },
    silver: { 
      icon: <PremiumIcon />, 
      color: isLight ? '#616161' : '#e0e0e0', 
      bg: isLight ? 'linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%)' : 'linear-gradient(135deg, #424242 0%, #616161 100%)',
    },
  };

  const config = defaults[tier] || defaults.silver;

  if (customColor) {
    // If a custom color is provided from API, use it to generate a matching theme
    return {
      ...config,
      color: isLight ?  alpha(customColor, 0.9) : customColor,
      bg: isLight 
        ? `linear-gradient(135deg, ${alpha(customColor, 0.1)} 0%, ${alpha(customColor, 0.3)} 100%)`
        : `linear-gradient(135deg, ${alpha(customColor, 0.2)} 0%, ${alpha(customColor, 0.4)} 100%)`
    };
  }

  return config;
};

