// Language Section (used in "All" view and single-language view)
const LanguageSection = ({ language, showLabel, onPurchase, purchasedCoursesByMajor }) => {
  const theme = useTheme();
  const purchasedSet = useMemo(() => {
    const ids = purchasedCoursesByMajor?.[language.id] || [];
    return new Set(ids.map((id) => Number(id)));
  }, [purchasedCoursesByMajor, language.id]);

  const handlePurchase = (planOrCourse) => {
    const isBundle = typeof planOrCourse?.tier === 'string';
    const resolvedCourses = isBundle ? planOrCourse.courses : [planOrCourse.id];
    onPurchase({ ...planOrCourse, major: language.id, courses: resolvedCourses });
  };

  return (
    <Box>
      {showLabel && (
        <Stack direction="row" alignItems="center" spacing={1.5} sx={{ mb: 2 }}>
          <Typography fontSize="1.5rem">{language.icon}</Typography>
          <Typography variant="h6" fontWeight={800}>{language.name}</Typography>
        </Stack>
      )}

      {/* Bundle Plans */}
      {language.bundlePlans?.length > 0 && (
        <Box sx={{ mb: 3 }}>
          {!showLabel && (
            <Typography variant="subtitle1" fontWeight={800} sx={{ mb: 2 }}>
              Recommended Plans
            </Typography>
          )}
          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: {
                xs: '1fr',
                md: language.bundlePlans.length <= 3
                  ? `repeat(${language.bundlePlans.length}, 1fr)`
                  : 'repeat(3, 1fr)',
              },
              gap: 2,
            }}
          >
            {language.bundlePlans.map((plan, i) => (
              <BundlePlanCard
                key={i}
                plan={plan}
                isPopular={plan.tier === 'diamond'}
                allCourses={language.courses}
                isPurchased={Array.isArray(plan.courses) && plan.courses.length > 0 && plan.courses.every((id) => purchasedSet.has(Number(id)))}
                onPurchase={handlePurchase}
              />
            ))}
          </Box>
        </Box>
      )}

      {/* Individual Courses */}
      <Box sx={{ mb: showLabel ? 3 : 4 }}>
        {!showLabel && (
          <Typography variant="subtitle1" fontWeight={800} sx={{ mb: 2 }}>
            All Courses
          </Typography>
        )}
        <Paper
          elevation={0}
          sx={{ 
            overflow: 'hidden', 
            border: '1px solid', 
            borderColor: 'divider',
            borderRadius: 3,
            boxShadow: '0 2px 8px rgba(0,0,0,0.04)'
          }}
        >
          {language.courses.map((course, i) => (
            <CourseRow
              key={i}
              course={course}
              isLast={i === language.courses.length - 1}
              isPurchased={purchasedSet.has(Number(course.id))}
              onPurchase={handlePurchase}
            />
          ))}
        </Paper>
      </Box>
    </Box>
  );
};

