const VipPlan = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState(0); // 0 = All, 1 = English, 2 = Korean
  const [copied, setCopied] = useState(null);
  
  // Payment Modal State
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        // Attempt to fetch from API
        const response = await vipPlanAPI.get();
        if (response.data && response.data.languages) {
          setData(response.data);
        } else {
          // Fallback to mock data if structure doesn't match or empty
          console.warn('API response empty or invalid structure, using mock data');
          setData(MOCK_DATA.data);
        }
      } catch (err) {
        console.error('Failed to load VIP plan data, using mock data:', err);
        // Fallback to mock data on error
        setData(MOCK_DATA.data);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(text);
      setTimeout(() => setCopied(null), 2000);
    });
  };

  const handlePurchase = (planOrCourse) => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }
    setSelectedPlan(planOrCourse);
    setPaymentModalOpen(true);
  };

  const handlePaymentSuccess = () => {
    setSnackbar({
      open: true,
      message: 'Payment submitted successfully! We will review it shortly.',
      severity: 'success'
    });
  };

  const handleSnackbarClose = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  // Build tab list: All + each language
  const tabs = useMemo(() => {
    if (!data) return [];
    return [
      { id: 'all', label: 'All', icon: '📋' },
      ...data.languages.map((lang) => ({ id: lang.id, label: lang.name, icon: lang.icon })),
    ];
  }, [data]);

  if (loading) return <VipPlanSkeleton />;

  if (!data) {
    return (
      <Box sx={{ textAlign: 'center', py: 4, px: { xs: 2, sm: 3 } }}>
        <Typography variant="subtitle1" color="error">Failed to load plan data</Typography>
        <Button variant="contained" size="small" sx={{ mt: 2 }} onClick={() => window.location.reload()}>Try Again</Button>
      </Box>
    );
  }

  const isAll = activeTab === 0;
  const activeLanguage = !isAll ? data.languages[activeTab - 1] : null;

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default' }}>
      <Container maxWidth="lg" sx={{ py: { xs: 2, md: 4 }, px: { xs: 2, sm: 3 } }}>

        {/* Page Header - Simple & Clean */}
        <Box sx={{ mb: 3, textAlign: 'center' }}>
          <Chip 
            label="VIP Membership" 
            color="primary" 
            size="small" 
            sx={{ mb: 1, fontWeight: 700, textTransform: 'uppercase', letterSpacing: 0.5, height: 24, fontSize: '0.7rem' }} 
          />
          <Typography variant="h4" fontWeight={900} sx={{ letterSpacing: '-0.5px', mb: 1, fontSize: { xs: '1.5rem', md: '2rem' } }}>
            Choose Your Plan
          </Typography>
          <Typography variant="body2" color="text.secondary" fontWeight={400} sx={{ maxWidth: 500, mx: 'auto', lineHeight: 1.5 }}>
            Unlock your potential with our comprehensive language courses.
          </Typography>
        </Box>

        {/* Tab Filter */}
        <Box sx={{ mb: 4, display: 'flex', justifyContent: 'center' }}>
          <Tabs
            value={activeTab}
            onChange={(_, v) => setActiveTab(v)}
            variant="scrollable"
            scrollButtons="auto"
            allowScrollButtonsMobile
            sx={{
              bgcolor: 'background.paper',
              borderRadius: '50px',
              p: 0.5,
              boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
              border: '1px solid',
              borderColor: 'divider',
              minHeight: 36,
              '& .MuiTabs-indicator': {
                display: 'none',
              },
              '& .MuiTab-root': {
                minHeight: 36,
                py: 0.5,
                px: 2,
                borderRadius: '40px',
                fontWeight: 700,
                fontSize: '0.8rem',
                textTransform: 'none',
                color: 'text.secondary',
                transition: 'all 0.2s',
                mr: 0.5,
                '&:last-child': { mr: 0 },
                '&.Mui-selected': {
                  bgcolor: 'primary.main',
                  color: 'primary.contrastText',
                  boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
                },
                '&:hover:not(.Mui-selected)': {
                  bgcolor: alpha(theme.palette.primary.main, 0.08),
                }
              },
            }}
          >
            {tabs.map((tab) => (
              <Tab
                key={tab.id}
                label={
                  <Stack direction="row" alignItems="center" spacing={0.5}>
                    <Typography component="span" fontSize="1rem">{tab.icon}</Typography>
                    <span>{tab.label}</span>
                  </Stack>
                }
              />
            ))}
          </Tabs>
        </Box>

        {/* Content */}
        {isAll ? (
          // ALL tab: show each language in sequence
          <Stack spacing={4}>
            {data.languages.map((lang, idx) => (
              <Box key={lang.id}>
                <LanguageSection language={lang} showLabel onPurchase={handlePurchase} purchasedCoursesByMajor={data?.purchasedCoursesByMajor} />
                {idx < data.languages.length - 1 && <Divider sx={{ my: 4, opacity: 0.5 }} />}
              </Box>
            ))}
          </Stack>
        ) : (
          // Single language tab
          <LanguageSection language={activeLanguage} showLabel={false} onPurchase={handlePurchase} purchasedCoursesByMajor={data?.purchasedCoursesByMajor} />
        )}

        <Divider sx={{ my: 5 }} />

        {/* Payment Methods */}
        <Box sx={{ mb: 5 }}>
          <Box sx={{ textAlign: 'center', mb: 3 }}>
            <Typography variant="h6" fontWeight={800} gutterBottom>
              Payment Methods
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Secure and convenient ways to pay
            </Typography>
          </Box>

          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: { xs: '1fr', sm: 'repeat(2, 1fr)', md: 'repeat(3, 1fr)' },
              gap: 1.5,
            }}
          >
            {data.paymentMethods.map((method, i) => (
              <PaymentMethodCard key={i} method={method} onCopy={handleCopy} copied={copied} />
            ))}
          </Box>
        </Box>


        {/* Contact Info */}
        <Box sx={{ textAlign: 'center', bgcolor: alpha(theme.palette.primary.main, 0.03), borderRadius: 6, p: { xs: 3, md: 4 } }}>
          <Typography variant="subtitle1" fontWeight={800} gutterBottom>
            Need Help?
          </Typography>
          <Typography variant="caption" display="block" color="text.secondary" sx={{ mb: 3, fontSize: '0.8rem' }}>
            Contact our support team for any questions.
          </Typography>
          
          <Stack 
            direction={{ xs: 'column', sm: 'row' }} 
            spacing={1.5} 
            justifyContent="center"
            flexWrap="wrap"
            useFlexGap
          >
            {/* Phone Numbers */}
            {data.contact?.phone?.map((phone, idx) => {
              const cleanPhone = phone.replace(/\s/g, '');
              return (
                <Button
                  key={idx}
                  variant="outlined"
                  size="medium"
                  startIcon={<PhoneIcon fontSize="small" />}
                  onClick={() => handleCopy(cleanPhone)}
                  sx={{
                    py: 1,
                    px: 2.5,
                    borderRadius: '50px',
                    textTransform: 'none',
                    fontWeight: 700,
                    fontSize: '0.85rem',
                    bgcolor: 'background.paper',
                    borderColor: 'divider',
                    color: 'text.primary',
                    '&:hover': {
                      borderColor: 'primary.main',
                      bgcolor: 'background.paper',
                    }
                  }}
                >
                  {phone} 
                  {copied === cleanPhone && (
                    <Chip 
                      label="Copied" 
                      color="success" 
                      size="small" 
                      sx={{ ml: 1, height: 18, fontSize: '0.6rem' }} 
                    />
                  )}
                </Button>
              );
            })}

            {/* Facebook */}
            {data.contact?.facebook && (
              <Button
                variant="outlined"
                size="medium"
                startIcon={<FacebookIcon fontSize="small" />}
                href={data.contact.facebook}
                target="_blank"
                rel="noopener noreferrer"
                sx={{
                  py: 1,
                  px: 2.5,
                  borderRadius: '50px',
                  textTransform: 'none',
                  fontWeight: 700,
                  fontSize: '0.85rem',
                  bgcolor: 'background.paper',
                  borderColor: '#1877F2',
                  color: '#1877F2',
                  '&:hover': {
                    bgcolor: '#1877F2',
                    color: 'white',
                  }
                }}
              >
                Facebook
              </Button>
            )}

            {/* Viber */}
            {data.contact?.viber && (
              <Button
                variant="outlined"
                size="medium"
                startIcon={<ChatIcon fontSize="small" />}
                href={data.contact.viber}
                target="_blank"
                rel="noopener noreferrer"
                sx={{
                  py: 1,
                  px: 2.5,
                  borderRadius: '50px',
                  textTransform: 'none',
                  fontWeight: 700,
                  fontSize: '0.85rem',
                  bgcolor: 'background.paper',
                  borderColor: '#7360f2',
                  color: '#7360f2',
                  '&:hover': {
                    bgcolor: '#7360f2',
                    color: 'white',
                  }
                }}
              >
                Viber
              </Button>
            )}
          </Stack>
        </Box>

        <Box sx={{ mt: 5 }}>
          <FAQSection />
        </Box>

      </Container>
      
      {/* Payment Modal */}
      {selectedPlan && (
        <PaymentModal
          open={paymentModalOpen}
          onClose={() => setPaymentModalOpen(false)}
          plan={selectedPlan}
          courses={Array.isArray(selectedPlan.courses) && selectedPlan.courses.length > 0 ? selectedPlan.courses : [selectedPlan.id]}
          paymentMethods={data?.paymentMethods || []}
          onSuccess={handlePaymentSuccess}
        />
      )}

      {/* Success Snackbar */}
      <Snackbar 
        open={snackbar.open} 
        autoHideDuration={6000} 
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleSnackbarClose} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default VipPlan;
